# ╔══════════════════════════════════════════════════════════════════════════╗
# ║ Guard — every live service's src/build-*.json must resolve to a file      ║
# ║ that EXISTS in cloud-infra's 1_cloud-configs/dist.                       ║
# ╚══════════════════════════════════════════════════════════════════════════╝
#
# THE DEFECT THIS EXISTS FOR (#564, measured 2026-09-24)
#
# A service's src/flake.nix reads its per-container config by NAME:
#
#     container = builtins.fromJSON (builtins.readFile ./build-cloud-agi-claude.json);
#
# and that name is GENERATED. cloud-infra's emitter writes one file per
# container as `build-${containerName}.json`, where containerName is
# `containers.<role>.container_name` falling back to the service name
# (1_cloud-configs/src/derive/cloud-data-config-derive.ts, `deriveContainerConfigs`).
#
# So renaming containers.app.container_name MOVES a filename in dist. It is not
# a one-field change. #542 renamed three agent containers to cloud-agi-*, and:
#
#   • user-ai_my-ai_claude-api kept the old symlink name. nix reads from git, so
#     a target that is gone reads as "Path '...src/build-my-ai_claude-api.json'
#     does not exist in Git repository" and the build died before Docker.
#     Ship run 35995862469. LOUD.
#
#   • user-ai_hermes-agent had the identical dangling symlink and simply had not
#     shipped yet. LATENT.
#
#   • user-ai_my-ai-api was not a symlink at all — a 52,827-byte REGULAR FILE
#     whose dist name was also gone. It BUILT, from a frozen pre-rename config
#     (secret_env_vars missing GH_TOKEN, runtime.call_timeout_ms 180000 instead
#     of 860000, runtime.claude_model and runtime.sessions.{name,resume} absent,
#     .services still naming four retired services). SILENT, and strictly worse
#     than the loud failure.
#
# #542's own naming tester asserted container_name VALUES and went green.
# Nothing asserted that the declaration still RESOLVES. That is this file.
# #561 (cloud-myIDE → Cloud-MyTerminal) and #563 (Constellation → Store) are
# queued renames of the same shape and hit the same wall.
#
# WHY A NAME MISSING FROM dist IS NOT AUTOMATICALLY A FAILURE
#
# dist is regenerated by ship-gen-configs, which runs in PARALLEL with Ship on a
# containers-push and commits afterwards. On the very push that performs a
# rename, dist therefore still holds the OLD name and not yet the new one. A
# strict "must be in dist" check would go red on every correct rename and green
# one cycle later — noise that teaches people to ignore it.
#
# So a name absent from dist passes ONLY when the current tree's own build.json
# declares it, i.e. when it is exactly what the emitter is about to write. That
# is lag-immune and still catches #542: after the rename NO build.json declares
# container_name my-ai_claude-api, so the stale symlink fails immediately, at
# the commit that broke it, instead of at the next unlucky deploy.
#
# NOT ENFORCED HERE, DELIBERATELY: build-*.json that are REGULAR FILES and that
# no flake reads. infra-api_google-workspace-mcp/src (123) and
# infra-api_cloud-mattermost-mcp/src (63) hold a 2026-08-29 snapshot of the
# whole fleet's dist dropped into two service directories; each flake reads only
# its own. They are reported as a count, not failed on — converting them is its
# own ticket, because a frozen copy and a link can build differently.
#
# Usage: bash 9_others/test/test_build_json_targets_resolve.sh
#        (needs a_solutions/ checked out — lint-pipeline's registered-testers
#         job does that; see the job's "Checkout cloud-u-containers" step)
set -uo pipefail

# Repo root by upward search, not a fixed ../../.. — this file is copied to
# 1_cicd/dist/test/ as well, which sits at a different depth.
REPO_ROOT="$(_d="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; while [ "$_d" != "/" ] && [ ! -e "$_d/.git" ]; do _d="$(dirname "$_d")"; done; printf '%s' "$_d")"

FAIL=0
pass() { printf "  ✓ %s\n" "$1"; }
fail() { printf "  ✗ %s\n" "$1" >&2; FAIL=1; }
note() { printf "  · %s\n" "$1"; }

command -v jq >/dev/null || { echo "::error::jq is required"; exit 1; }

# ── The emitter's own naming rule, applied to ONE build.json ────────────────
# `build-${container_name || service name}.json`, plus the db_engine alias the
# emitter also writes (cloud-data-config-derive.ts). Printed one per line.
#
# PER-SERVICE on purpose, and this is the whole difference between a guard and a
# rubber stamp. A first cut unioned these names across the whole fleet, and both
# of #542's stale spellings passed it: some OTHER service's build.json carries
# `.name` values that collide with the retired names, so "some build.json
# declares it" was satisfied by a service that has nothing to do with the link.
# A service's OWN readFile target must be a name THAT service declares.
emit_expected_names() {
    jq -r '
      (.name // "") as $n
      | (.containers // {}) | to_entries[]
      | ("build-" + (.value.container_name // $n) + ".json"),
        (if (.value.db_engine // "") != "" then "build-" + .value.db_engine + ".json" else empty end)
    ' "$1" 2>/dev/null | grep -v '^build-\.json$' | sort -u
}

# ── The check. Pure over (services tree, dist filename list). ──────────────
# Prints findings; returns 0 clean, 1 on any violation. Never `exit`s, so the
# mutation cases below can call it repeatedly.
check_tree() {
    local svcroot="$1" distlist="$2" quiet="${3:-}"
    local rc=0 own fleet frozen_unread=0 frozen_read=0
    # The union is used ONLY for cross-references (part B): a link into another
    # service's generated config is legitimately named after THAT service.
    fleet="$(for _b in "$svcroot"/*/build.json; do [ -f "$_b" ] && emit_expected_names "$_b"; done | sort -u)"

    _in_dist()  { grep -qxF "$1" "$distlist"; }
    _own()      { printf '%s\n' "$own"   | grep -qxF "$1"; }
    _fleet()    { printf '%s\n' "$fleet" | grep -qxF "$1"; }
    _say()      { [ -n "$quiet" ] || printf '%s\n' "$1"; }

    local bj svc flake ref path target base
    for bj in "$svcroot"/*/build.json; do
        [ -f "$bj" ] || continue
        svc="$(basename "$(dirname "$bj")")"
        flake="$svcroot/$svc/src/flake.nix"
        own="$(emit_expected_names "$bj")"

        # ── A) every name a flake.nix actually READS ───────────────────────
        # These are load-bearing: nix evaluates readFile, so an unresolvable
        # name is a hard build error (the claude-api shape) or a frozen copy
        # silently outliving the rename (the my-ai-api shape).
        if [ -f "$flake" ]; then
            while IFS= read -r ref; do
                [ -n "$ref" ] || continue
                path="$svcroot/$svc/src/$ref"
                if [ -L "$path" ]; then
                    target="$(readlink "$path")"
                    base="$(basename "$target")"
                    # -e is useless here: these links point at
                    # ../../../1_cloud-configs/dist/, which resolves only in the
                    # BUILDER layout (cloud-u-containers checked out AT
                    # cloud-infra/a_solutions/). Compare BASENAMES against the
                    # real dist listing instead — a dangling-looking link on a
                    # dev box is correct, a wrong basename never is.
                    if _in_dist "$base"; then
                        :
                    elif _own "$base"; then
                        _say "  · $svc/src/$ref → $base: not in dist YET, but $svc/build.json declares that container_name (gen-configs lag) — OK"
                    else
                        _say "  ✗ $svc/src/$ref → $base: NOT in cloud-infra dist, and $svc/build.json declares [$(printf '%s' "$own" | tr '\n' ' ')]. flake.nix readFile will fail with \"does not exist in Git repository\". A container rename moved this name." >&2
                        rc=1
                    fi
                elif [ -f "$path" ]; then
                    # A regular file is a FROZEN copy: it cannot fail loudly, so
                    # the only signal that the rename moved past it is that dist
                    # no longer carries its name.
                    if _in_dist "$ref"; then
                        frozen_read=$((frozen_read + 1))
                        _say "  · $svc/src/$ref: regular file, not a symlink — builds from a frozen copy, dist still carries the name (see #564, not failed here)"
                    else
                        _say "  ✗ $svc/src/$ref: regular file AND no such name in cloud-infra dist. This service builds from a frozen pre-rename config and cannot fail loudly about it — the user-ai_my-ai-api shape (#564)." >&2
                        rc=1
                    fi
                else
                    _say "  ✗ $svc/src/flake.nix reads ./$ref but no such file exists in the service tree." >&2
                    rc=1
                fi
            done < <(grep -oE 'readFile \./build-[A-Za-z0-9._-]+\.json' "$flake" 2>/dev/null | sed 's|.*\./||' | sort -u)
        fi

        # ── B) every build-*.json SYMLINK under src/, read or not ──────────
        # A dangling one is dead weight that reads as a live cross-reference;
        # two of them (build-my-ai_claude-api.json under
        # infra-api_cloud-mattermost-mcp and infra-api_google-workspace-mcp)
        # survived #542 and were what made the rename look like it had more
        # live consumers than it did.
        while IFS= read -r path; do
            [ -n "$path" ] || continue
            target="$(readlink "$path")"
            base="$(basename "$target")"
            _in_dist "$base" && continue
            _fleet "$base" && continue
            _say "  ✗ ${path#$svcroot/}: symlink → $base, which is neither in cloud-infra dist nor declared by any build.json in the fleet." >&2
            rc=1
        done < <(find "$svcroot/$svc/src" -name 'build-*.json' -type l 2>/dev/null | sort)
    done

    # ── C) report-only: frozen copies no flake reads ──────────────────────
    frozen_unread=$(find "$svcroot"/*/src -name 'build-*.json' -type f 2>/dev/null | wc -l)
    _say "  · $frozen_unread build-*.json exist as REGULAR FILES across live service src/ trees ($frozen_read of them are a flake readFile target). Reported, not failed: converting a frozen copy to a link can change what a container builds from."

    unset -f _in_dist _own _fleet _say
    return $rc
}

# ══════════════════════════════════════════════════════════════════════════
echo "── 1: the real tree — every live service's build-*.json resolves ──"

SVCROOT="$REPO_ROOT/a_solutions"
DIST="$REPO_ROOT/1_cloud-configs/dist"

if [ ! -d "$SVCROOT" ]; then
    # Not a skip. A missing a_solutions means this guard checked nothing, and a
    # guard that checks nothing must never be the reason a run is green (#368).
    echo "::error::a_solutions/ is not checked out — this guard cannot verify anything. The job must check out diegonmarcos/cloud-u-containers into a_solutions/ before running it."
    exit 1
fi
[ -d "$DIST" ] || { echo "::error::$DIST missing — run 1_cloud-configs/build.sh"; exit 1; }

DISTLIST="$(mktemp)"; trap 'rm -f "$DISTLIST"' EXIT
find "$DIST" -maxdepth 1 -name 'build-*.json' -printf '%f\n' | sort > "$DISTLIST"
note "$(wc -l < "$DISTLIST") build-*.json in $(basename "$(dirname "$DIST")")/$(basename "$DIST")"

if check_tree "$SVCROOT" "$DISTLIST"; then
    pass "every live service's src/build-*.json resolves to a real dist file"
else
    fail "at least one src/build-*.json does not resolve — see the ✗ lines above"
fi

# ══════════════════════════════════════════════════════════════════════════
# MUTATION PROOF. A guard that only ever sees a clean tree is indistinguishable
# from `exit 0`, which is the defect shape this repo keeps finding. Each case
# below breaks the tree in exactly one of the ways #542 broke it and asserts
# this guard NOTICES — plus one case asserting it does NOT fire on a correct
# rename, because a guard that cries wolf gets ignored and is then not a guard.
echo ""
echo "── 2: mutation proof ──"

TMP="$(mktemp -d)"; trap 'rm -f "$DISTLIST"; rm -rf "$TMP"' EXIT

mk_fixture() {
    # A minimal two-service tree in the same shape as the real one.
    local root="$TMP/$1"; rm -rf "$root"; mkdir -p "$root/svc-a/src" "$root/svc-b/src"
    printf '{"name":"svc-a","containers":{"app":{"container_name":"cloud-agi-alpha"}}}\n' > "$root/svc-a/build.json"
    printf '{"name":"svc-b","containers":{"app":{}}}\n'                                  > "$root/svc-b/build.json"
    printf 'container = builtins.fromJSON (builtins.readFile ./build-cloud-agi-alpha.json);\n' > "$root/svc-a/src/flake.nix"
    printf 'container = builtins.fromJSON (builtins.readFile ./build-svc-b.json);\n'           > "$root/svc-b/src/flake.nix"
    ln -s ../../../1_cloud-configs/dist/build-cloud-agi-alpha.json "$root/svc-a/src/build-cloud-agi-alpha.json"
    ln -s ../../../1_cloud-configs/dist/build-svc-b.json           "$root/svc-b/src/build-svc-b.json"
    printf '%s\n' "$root"
}
FDIST="$TMP/dist.txt"
printf 'build-cloud-agi-alpha.json\nbuild-svc-b.json\n' > "$FDIST"

expect() { # expect <0|1> <label> <tree>
    local want="$1" label="$2" tree="$3" got
    check_tree "$tree" "$FDIST" quiet >/dev/null 2>&1; got=$?
    if [ "$got" -eq "$want" ]; then
        pass "$label (exit $got)"
    else
        fail "$label — expected exit $want, got $got. This guard does not actually detect what it claims to."
    fi
}

# M1 — clean fixture must pass, or every other case below proves nothing.
expect 0 "clean tree passes" "$(mk_fixture m1)"

# M2 — the claude-api / hermes shape: rename happened, symlink kept the OLD
#      name, and no build.json declares it any more. Run 35995862469.
T="$(mk_fixture m2)"
rm "$T/svc-a/src/build-cloud-agi-alpha.json"
ln -s ../../../1_cloud-configs/dist/build-old-name.json "$T/svc-a/src/build-cloud-agi-alpha.json"
expect 1 "flake's symlink target missing from dist is caught" "$T"

# M3 — the my-ai-api shape: the readFile target is a REGULAR FILE whose dist
#      name is gone. Builds fine, silently, from a pre-rename config.
T="$(mk_fixture m3)"
rm "$T/svc-a/src/build-cloud-agi-alpha.json"
printf '{"container":{"container_name":"stale"}}\n' > "$T/svc-a/src/build-cloud-agi-alpha.json"
printf 'container = builtins.fromJSON (builtins.readFile ./build-gone.json);\n' > "$T/svc-a/src/flake.nix"
cp "$T/svc-a/src/build-cloud-agi-alpha.json" "$T/svc-a/src/build-gone.json"
expect 1 "frozen regular file whose dist name is gone is caught" "$T"

# M4 — a dangling build-*.json symlink no flake reads: the two vestigial
#      build-my-ai_claude-api.json cross-references #542 left behind.
T="$(mk_fixture m4)"
ln -s ../../../1_cloud-configs/dist/build-retired.json "$T/svc-b/src/build-retired.json"
expect 1 "dangling symlink that no flake reads is caught" "$T"

# M5 — a CORRECT rename, pushed before gen-configs has refreshed dist: the new
#      name is declared by build.json but not in the listing yet. Must NOT fire,
#      or this guard reds every rename once and gets ignored.
T="$(mk_fixture m5)"
printf '{"name":"svc-a","containers":{"app":{"container_name":"cloud-agi-renamed"}}}\n' > "$T/svc-a/build.json"
rm "$T/svc-a/src/build-cloud-agi-alpha.json"
ln -s ../../../1_cloud-configs/dist/build-cloud-agi-renamed.json "$T/svc-a/src/build-cloud-agi-renamed.json"
printf 'container = builtins.fromJSON (builtins.readFile ./build-cloud-agi-renamed.json);\n' > "$T/svc-a/src/flake.nix"
expect 0 "a correct rename not yet in dist does NOT false-red" "$T"

# M6 — flake reads a name that has no file at all.
T="$(mk_fixture m6)"
printf 'container = builtins.fromJSON (builtins.readFile ./build-absent.json);\n' > "$T/svc-a/src/flake.nix"
expect 1 "flake reading a name with no file at all is caught" "$T"

echo ""
[ "$FAIL" -eq 0 ] && echo "PASS: build-*.json declarations resolve, and the guard is proven to detect when they do not." \
                  || echo "FAIL: see ✗ above"
exit "$FAIL"
